{
    "name": "ip2countrify",
    "version": "0.2.0",
    "description": "A Node.js wrapper for IP2Country JSON API",
    "main": "index.js",
    "scripts": {
        "test": "mocha",
        "lint": "eslint ."
    },
    "keywords": [
        "geo",
        "geoip",
        "geolocation",
        "country"
    ],
    "author": {
        "name": "Sergej Müller",
        "url": "https://sergejmueller.github.io"
    },
    "homepage": "https://ip2country.info",
    "repository": "sergejmueller/ip2countrify",
    "license": "MIT",
    "devDependencies": {
        "chai": "^3.5.0",
        "mocha": "^3.1.0",
        "eslint": "^3.8.1",
        "eslint-plugin-node": "^2.1.3"
    },
    "engines": {
        "node": ">=0.10"
    }
}

"use strict";

var ip2countrify = require( '..' ),
    expect = require( 'chai' ).expect;


describe( 'API requests', function() {

    /*
        IPv6 Test
    */

    it( 'IPv6 test', function( done ) {
        ip2countrify.lookup(
            '2001:420:1101:1::a',
            function( ip, results ) {
                expect( results.countryCode ).to.equal( 'US' );
                expect( results.countryCode3 ).to.equal( 'USA' );
                expect( results.countryName ).to.equal( 'United States' );
                expect( results.countryEmoji ).to.equal( '🇺🇸' );

                done();
            }
        );
    } );


    /*
        IPv4 Test
    */

    it('IPv4 test', function( done ) {
        ip2countrify.lookup(
            '5.6.7.8',
            function( ip, results ) {
                expect( results.countryCode ).to.equal( 'DE' );
                expect( results.countryCode3 ).to.equal( 'DEU' );
                expect( results.countryName ).to.equal( 'Germany' );
                expect( results.countryEmoji ).to.equal( '🇩🇪' );

                done();
            }
        );
    });

} );

"use strict";


var https = require( 'https' ),
    net = require( 'net' );


module.exports = {

    lookup: function( ip, callback ) {
        if ( ! ip ) {
            return callback(
                ip,
                null,
                'Empty IP'
            );
        }

        if ( net.isIP( ip ) === 0 ) {
            return callback(
                ip,
                null,
                'Invalid IP'
            );
        }

        var options = {
            method: 'GET',
            host: 'api.ip2country.info',
            path: '/ip?' + ip,
            headers: {
                'User-Agent': 'ip2countrify'
            }
        };

        var request = https.request( options, function( response ) {

            var body = [];

            response.on( 'data', function( chunk ) {

                body.push( chunk );

            } ).on( 'end', function() {

                body = Buffer.concat( body ).toString();

                return callback(
                    ip,
                    JSON.parse( body ),
                    null
                );

            } ).on( 'error', function( error ) {

                return callback(
                    ip,
                    null,
                    error.message
                );

            } );
        } );

        request.end();
    }

};

"use strict";


var ip2countrify = require( '..' );


/*
    IPv6 lookup
*/

ip2countrify.lookup(
    '2001:420:1101:1::a',
    function( ip, results, error ) {

        if ( error ) {
            return console.warn( 'An error has occurred: ' + error );
        }

        console.log(
            'API results for ' + ip
        );
        console.log(
            'countryCode: ' + results.countryCode,
            'countryCode3: ' + results.countryCode3,
            'countryName: ' + results.countryName,
            'countryEmoji: ' + results.countryEmoji
        );

    }
);

